INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_profile_contact_and_continuity", "族群簡介", "卑南族公開介紹同時呈現早期與外界接觸及持續維持傳統文化生活兩個面向，主站文章應避免把接觸史等同文化斷裂。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_36d3ba1bf3aa34fd", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_profile_age_hall_not_optional", "社會制度", "年齡階級與會所制度在卑南族公開介紹中是核心描述，不應在主站內容中被簡化成一般活動空間。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_00865a8b9989c573", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_population_zh_versioned", "人口版本治理", "原民會中文頁目前列示卑南族總人口 16,734；此數值應保存資料日期與來源版本，不能與英文舊頁人口混寫。", "[\"cip_pinuyumayan_profile_zh_current\"]", "claim_e636dd658a8c06ba", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_population_en_historical", "人口版本治理", "原民會英文頁保留 2020 年 1 月約 14,517 的舊人口描述，適合作為歷史版本而非最新人口。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_9f2df8d8989e82dd", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_name_nanwang_origin_boundary", "族稱與命名", "原民會英文頁說明 Pinuyumayan 名稱脈絡與南王村名相關；平台需將族群名稱與單一部落名稱做欄位區分。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_289e59e821fb8320", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_origin_bamboo_stone_summary", "族群歷史摘要", "公開介紹提到竹生與石生兩類起源來源；平台只保存公開摘要與來源，不擴寫神話細節。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_bc1210be508cf8b6", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_pinadray_period_summary", "族群歷史摘要", "原民會英文頁提到卑南族在 17 世紀以前曾是強勢族群，並在 Pinadray 時期達高峰；主站應標示此為官方頁摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_46d0d544232ac2af", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_sukaro_migration_summary", "族群歷史摘要", "18 世紀部分族人遷往恆春半島的 sukaro 敘述，應作為遷移史候選主題並保留來源定位。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_9810a7933805c4fa", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_japanese_period_eight_tribes_label", "族群分類史", "原民會英文頁提到日治時期因八社而出現 ethnological label；平台可作分類史摘要，但不得用八社取代目前主站十社資料模型。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_0248cb3424971169", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_taitung_beinan_center", "地理分布", "臺東市與卑南鄉被原民會英文頁描述為今日卑南族中心區域，主站地圖應以此作為主要分布基準。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_611f5244c6df45dd", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_chenggong_taimali_settlement", "地理分布", "原民會英文頁也提到部分卑南族人定居成功鎮與太麻里鄉，主站可列為延伸居住摘要而非十社核心。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_e30e852763c646df", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_major_tribes_source_list", "部落資料", "原民會英文頁列出知本、建和、南王、寶桑、利嘉、泰安、上賓朗、下賓朗、初鹿、龍過脈等主要部落；主站應保留羅馬拼寫與中文名對照。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_36b3831d59053342", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_urban_migration_context", "族群現況", "原民會英文頁提到許多卑南族人離開東部到城市發展，主站社群功能可支持離鄉族人的連結情境。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_5aa43ffcb673a92e", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_millet_agriculture_origin", "生業", "公開資料指出卑南族農業以小米開始；主站生業內容應把小米放在農業史摘要核心。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_1370ca8da179ca70", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_rice_technology_pinadray", "生業", "原民會英文頁將稻作技術與設備引入和 Pinadray 時期農業高峰相連；平台應保存為來源摘要並避免過度推論。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_584d908c1e56e734", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_cash_crop_shift_1960s", "生業", "1960 年代以後轉向釋迦、檳榔等經濟作物的描述，可作為近現代生業變遷摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_184016c5b4bd04cc", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_food_staple_group", "飲食", "傳統主食可摘要為小米、旱稻、甘藷與芋頭；主站飲食卡需與來源對應。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_2dd85b340b91e17c", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_food_protein_sources", "飲食", "狩獵肉類、漁撈魚貝類在公開介紹中被列為蛋白質來源；主站只能做飲食史摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_f4d582e22be33070", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_shellflower_leaf_food", "飲食", "月桃葉包裹糯米與鹹豬肉的食物描述可作為節慶飲食公開摘要，需保留 Alpinia zerumbet 學名。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_47d962459cb50a16", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_betel_daily_and_ritual", "飲食與祭儀摘要", "檳榔在公開介紹中兼具日常生活與祭儀供品意義；平台應以摘要呈現，不擴展祭儀操作。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_bfe2fef867f2dabd", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_clothing_flax_material", "服飾", "原民會英文頁提到卑南族以麻製作衣物；服飾知識卡應將材料、色彩、紋樣分欄。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_432c2bc97c19f096", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_clothing_color_system", "服飾", "紅、黃、綠與黑白菱形、十字繡等元素可作公開服飾摘要，適合主站設計系統參考。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_30499ac4ce52c15e", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_clothing_social_status", "服飾與社會", "服飾在公開介紹中被描述為辨識性別、年齡與社會關係的方式；AI 文章不可把服飾只當裝飾。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_b95a73abeadde63b", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_wreath_social_relation_metric", "服飾與社會", "花環在公開介紹中與社群關係和友誼展現相關，可作為公開文化導覽摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_d69aa7edf732816c", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_weaving_techniques_summary", "工藝", "藤竹編採用 entrelac、herringbone、hexagonal 等技法的描述可作工藝摘要；需避免自行翻譯成未查證族語術語。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_a882bd84076aea62", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_weaving_tools_daily_life", "工藝", "藤籃、藤袋、背籃、竹杯、煙斗、漁獵陷阱等可作日常器物索引候選，需逐項來源化。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_af6f840bde94f08e", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_architecture_public_private", "建築", "卑南族建築在公開介紹中分為公共與私人用途；主站資料模型可建立 public/private building_type。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_0485d7667e2857b9", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_family_house_layout_summary", "建築", "家屋為長方形、茅草屋頂、竹壁、長邊開門、短邊開窗等描述可作建築公開摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_e9dc5afe286b7879", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_house_size_status_guardrail", "建築與社會", "公開介紹提到家屋大小可反映社會地位；主站應只保留摘要，不對現代家庭做推測。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_48cde8caf5b4e79b", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_dakuvan_age_range", "會所制度", "Dakuvan 少年會所與 12–13 歲進入的公開描述可作年齡階級摘要，但不得生成訓練教學。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_e8206ec7d3384abd", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_palakuan_age_range", "會所制度", "Palakuan 成年會所與 17–18 歲後續訓練的公開描述可作摘要，但不得把會所訓練轉成操作課程。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_d7b3ac551deb7406", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_music_poetic_lyrics", "音樂歌謠", "公開介紹說卑南族音樂節奏清楚、歌詞多敘事且富詩意；主站可作音樂導覽摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_9dfd9793463b443d", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_music_ritual_song_status_guardrail", "音樂歌謠", "祭儀歌在公開介紹中依工作與身分分類，主站只做分類摘要，不提供祭儀歌詞或操作語境。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_54073308442dc240", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_music_modern_artists_index", "音樂歌謠", "公開介紹列出多位具影響力的卑南族音樂人；主站可建人物候選索引，但人物頁需另查來源與肖像授權。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_e86768f42796607e", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_dance_status_steps_guardrail", "舞蹈", "舞蹈公開介紹與性別、年齡及社會身分相關；平台只能做摘要，不生成儀式舞步教學。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_7285f2cd99b063e6", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_language_north_south_influences", "語言", "原民會英文頁提到卑南語因部落與位置不同而有差異，南部知本受排灣/魯凱語影響，北部受阿美語發音影響。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_49748a69cc3e1358", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_language_taiwanese_contact", "語言", "因與漢人頻繁接觸，公開介紹也提到族人會說福佬話/臺語；主站語言頁可納入語言接觸摘要。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_125a85f6a64a8f99", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_social_roles_tripartite", "社會角色", "政治領袖、祭師與巫師在公開介紹中分屬不同專業角色；主站應分欄保存，不混成單一頭目概念。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_05dc0763d7695c1e", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_matrilineality_transition", "親屬制度", "公開介紹提到母系繼承與現代轉變；平台可建立「傳統／現代變遷」雙欄，不把任一描述絕對化。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_f78cf704e7715f7e", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_lineage_clan_taxonomy", "親屬制度", "Big Lineal Clan、Small Lineal Clan、Split Family 等公開描述可作親屬分類摘要，需保留英文術語來源。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_da8b9441621e0982", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_zhiben_clan_example", "親屬制度", "知本村三個 clan 共享祖先、chief 與會所的例子可作社會組織摘要，但需標為知本例子，不外推到所有部落。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_272a0e6a40f3ca32", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_cultural_revival_1991", "文化復振", "1991 年知本、初鹿、南王等地建立新會所、青年會與文化協會的描述，可作文化復振時間軸候選。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_96ef2f1114842673", "public", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_ritual_taxonomy_two_types", "祭儀公開摘要", "公開資料將祭儀概分為農業祭儀與生命祭儀；平台應將其作為分類架構，而非程序說明。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_3b4d34c06969b201", "public_summary_only", "verified_source_public_summary");
INSERT IGNORE INTO true_knowledge_claims_v34 (claim_id, category, statement_zh, source_ids, canonical_fingerprint, public_use, review_status) VALUES ("v34_ritual_calendar_months", "祭儀公開摘要", "公開頁列出三月 Mugamut、四月 Ruvuwa’an、七月 Masarut、十二月年祭等月曆摘要，主站可做年表卡。", "[\"cip_pinuyumayan_profile_en_2021\"]", "claim_715b6fbb2a43791e", "public_summary_only", "verified_source_public_summary");
